const driveResult = $('Create Report in Google Drive').first().json;
const report = $('Build Google Docs Report').first().json;

if (typeof driveResult.id !== 'string' || !driveResult.id.trim()) {
  throw new Error(
    'Google Drive error: document creation returned no file ID.'
  );
}

if (
  typeof report.finalAnswer !== 'string' ||
  !report.finalAnswer.trim()
) {
  throw new Error(
    'Final output error: report finalAnswer is missing.'
  );
}

const documentId = driveResult.id.trim();

const documentUrl =
  'https://docs.google.com/document/d/' +
  documentId +
  '/edit';

return [
  {
    json: {
      output:
        report.finalAnswer.trim() +
        '\n\nKaydedilen Google Docs raporu: ' +
        documentUrl,

      finalAnswer: report.finalAnswer.trim(),

      coverageScore:
        Number.isFinite(report.coverageScore)
          ? report.coverageScore
          : null,

      model:
        typeof report.model === 'string' && report.model.trim()
          ? report.model.trim()
          : 'gpt-5-mini',

      documentId,
      documentUrl,
    },
  },
];

const result = $input.first().json;

if (typeof result.finalAnswer !== 'string' || !result.finalAnswer.trim()) {
  throw new Error('Rapor hatası: Judge finalAnswer döndürmedi.');
}

if (!Array.isArray(result.answers) || result.answers.length === 0) {
  throw new Error('Rapor hatası: Judge Worker yanıtlarını döndürmedi.');
}

if (typeof result.question !== 'string' || !result.question.trim()) {
  throw new Error('Rapor hatası: asıl soru korunmadı.');
}

function splitMarkdownTableRow(line) {
  return line
    .trim()
    .replace(/^\|/, '')
    .replace(/\|$/, '')
    .split('|')
    .map(cell => cell.trim());
}

function isMarkdownTableSeparator(line) {
  const cells = splitMarkdownTableRow(line);
  return cells.length > 1
    && cells.every(cell => /^:?-{3,}:?$/.test(cell));
}

function convertMarkdownTables(input) {
  const lines = String(input || '').replace(/\r\n?/g, '\n').split('\n');
  const output = [];

  for (let index = 0; index < lines.length; index += 1) {
    const headerLine = lines[index];
    const separatorLine = lines[index + 1];
    const isTableStart = headerLine.includes('|')
      && typeof separatorLine === 'string'
      && isMarkdownTableSeparator(separatorLine);

    if (!isTableStart) {
      // Tek başına kalmış Markdown tablo ayraçlarını tamamen kaldır.
      if (!isMarkdownTableSeparator(headerLine)) output.push(headerLine);
      continue;
    }

    const headers = splitMarkdownTableRow(headerLine);
    const rows = [];
    index += 2;

    while (index < lines.length && lines[index].includes('|')) {
      const cells = splitMarkdownTableRow(lines[index]);
      if (!isMarkdownTableSeparator(lines[index]) && cells.some(Boolean)) {
        rows.push(cells);
      }
      index += 1;
    }

    index -= 1;
    output.push('');

    if (rows.length === 0) {
      output.push(headers.filter(Boolean).join(' - '));
    } else {
      rows.forEach(cells => {
        const firstHeader = headers[0] || '';
        const firstValue = cells[0] || '';
        if (firstValue) {
          const title = (firstHeader ? firstHeader + ': ' : '') + firstValue;
          output.push('• **' + title + '**');
        }
        headers.slice(1).forEach((header, offset) => {
          const value = cells[offset + 1] || '';
          if (header && value) output.push('  ' + header + ': ' + value);
        });
        output.push('');
      });
    }
  }

  return output.join('\n');
}

function normalizeMarkdownForDocs(input) {
  return convertMarkdownTables(input)
    // Sunum değerini düşüren tek başına "Kayıt 1" etiketlerini kaldır.
    .replace(/^\s*(?:\*{2})?Kayıt\s+\d+(?:\*{2})?\s*$/gmi, '')
    // Markdown başlıklarını gerçek kalın metin isteğine dönüştür.
    .replace(/^\s*#{1,6}\s+(.+)$/gm, '**$1**')
    // Markdown madde işaretlerini düz Unicode madde işaretine dönüştür.
    .replace(/^\s*[-*+]\s+/gm, '• ')
    // Tek yıldızlı italik işaretlerini kaldır; metni koru.
    .replace(/(^|[^\*])\*([^*\n]+)\*(?!\*)/g, '$1$2')
    .replace(/~~([^~\n]+)~~/g, '$1')
    .replace(/`([^`\n]+)`/g, '$1')
    // Modelin hatalı üretebildiği artık tablo ayraçlarını temizle.
    .replace(/^\s*\|?\s*:?-{3,}:?(?:\s*\|\s*:?-{3,}:?)+\s*\|?\s*$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function convertBoldMarkdown(input) {
  const source = String(input || '');
  const requests = [];
  let text = '';
  let cursor = 0;
  // Bir bold çifti başka bir satıra taşamaz. Böylece iki bağımsız bozuk
  // işaret arasında kalan sayfalar yanlışlıkla kalınlaştırılmaz.
  const pattern = /\*\*([^*\n]+)\*\*/g;
  let match;

  while ((match = pattern.exec(source)) !== null) {
    // Geçerli bir çiftin dışında kalan artık işaretleri metinden at.
    text += source.slice(cursor, match.index).replace(/\*\*/g, '');

    // Google Docs metin indeksleri 1'den başlar.
    const startIndex = text.length + 1;
    text += match[1];
    const endIndex = text.length + 1;

    if (endIndex > startIndex) {
      requests.push({
        updateTextStyle: {
          range: {
            startIndex,
            endIndex,
          },
          textStyle: {
            bold: true,
          },
          fields: 'bold',
        },
      });
    }

    cursor = match.index + match[0].length;
  }

  text += source.slice(cursor).replace(/\*\*/g, '');

  return {
    text,
    requests,
  };
}

const createdAt = new Date().toISOString();
// Analysis context belongs to the evidence channel, never to the reader's question.
const readerQuestion = result.question.split(/\n\nCSV analysis context\n/)[0].trim();
const shortQuestion = readerQuestion.replace(/[\r\n]+/g, ' ').slice(0, 70);
const documentTitle = 'Yönetici Karar Raporu - ' + shortQuestion + ' - ' + createdAt.slice(0, 10);
const contradictions = Array.isArray(result.unresolvedContradictions)
  ? result.unresolvedContradictions.filter(value => typeof value === 'string' && value.trim()) : [];
const rawReportText = [
  '**YÖNETİCİ KARAR RAPORU**',
  'Tarih: ' + createdAt.slice(0, 10),
  '',
  '**DEĞERLENDİRİLEN SORU**',
  readerQuestion,
  '',
  '**KARAR VE ÇÖZÜM**',
  result.finalAnswer,
  '',
  '**UZMAN YANITLARI**',
  ...result.answers.flatMap((entry, index) => [
    '',
    '**' + (index + 1) + '. ' + (entry.role || 'Uzman') + '**',
    entry.answer,
  ]),
  ...(contradictions.length ? ['', '**KARARI ETKİLEYEN BELİRSİZLİKLER**', ...contradictions.map(value => '• ' + value)] : []),
].join('\n');
const formattedReport = convertBoldMarkdown(normalizeMarkdownForDocs(rawReportText));
return [{ json: { ...result, createdAt, documentTitle,
  reportText: formattedReport.text, docsStyleRequests: formattedReport.requests } }];

const items = $input.all();

if (items.length === 0) {
  throw new Error(
    'Main aggregation error: no worker results were returned.'
  );
}

const results = items.map((item) => item.json);

const question = results[0].question;

if (
  typeof question !== 'string' ||
  !question.trim() ||
  results.some((result) => result.question !== question)
) {
  throw new Error(
    'Main aggregation error: worker question values are missing or inconsistent.'
  );
}

const model = results[0].model;

if (
  typeof model !== 'string' ||
  !model.trim() ||
  results.some((result) => result.model !== model)
) {
  throw new Error(
    'Main aggregation error: Worker model values are missing or inconsistent.'
  );
}

const answers = results
  .map((result, index) => {
    if (typeof result.answer !== 'string' || !result.answer.trim()) {
      throw new Error(
        `Main aggregation error: worker result ${index + 1} has no answer.`
      );
    }

    const agentId = Number(result.agentId);

    if (!Number.isInteger(agentId) || agentId < 1 || agentId > 10) {
      throw new Error(
        `Main aggregation error: worker result ${index + 1} has an invalid agentId.`
      );
    }

    return {
      agentId,
      role:
        typeof result.role === 'string' && result.role.trim()
          ? result.role.trim()
          : `Uzman ${agentId}`,
      task:
        typeof result.task === 'string' && result.task.trim()
          ? result.task.trim()
          : 'Görev belirtilmedi.',
      answer: result.answer.trim(),
      wordCount: Number(result.wordCount ?? 0),
      containsMarkdownTable:
        result.containsMarkdownTable === true,
    };
  })
  .sort((a, b) => a.agentId - b.agentId);

const uniqueIds = new Set(
  answers.map((answer) => answer.agentId)
);

if (uniqueIds.size !== answers.length) {
  throw new Error(
    'Main aggregation error: duplicate agentId values were returned.'
  );
}

const plan = $('Execute Planner Workflow').first().json;

if (!Number.isInteger(plan.agentCount) || plan.agentCount < 1) {
  throw new Error(
    'Main aggregation error: Planner agentCount is missing or invalid.'
  );
}

if (answers.length !== plan.agentCount) {
  throw new Error(
    `Main aggregation error: expected ${plan.agentCount} Worker results but received ${answers.length}.`
  );
}

return [
  {
    json: {
      question: question.trim(),
      model: model.trim(),
      questionType:
        typeof plan.questionType === 'string' &&
        plan.questionType.trim()
          ? plan.questionType.trim()
          : 'genel',
      complexity: ['low', 'medium', 'high'].includes(
        plan.complexity
      )
        ? plan.complexity
        : 'low',
      agentCount: answers.length,
      answers,
    },
  },
];

const plan = $input.first().json;

if (
  !Array.isArray(plan.agents) ||
  plan.agents.length < 1 ||
  plan.agents.length > 10
) {
  throw new Error(
    'Main split error: planner agents must contain 1 to 10 entries.'
  );
}

return plan.agents.map((agent, index) => ({
  json: {
    question: plan.question,
    model: plan.model ?? 'gpt-5-mini',
    questionType: plan.questionType,
    complexity: plan.complexity,
    agentCount: plan.agentCount ?? plan.agents.length,
    agentId: agent.agent_id ?? index + 1,
    role: agent.role,
    task: agent.task,
  },
}));

const chatInput = $input.first().json.chatInput;
const question = typeof chatInput === 'string' ? chatInput.trim() : '';
if (!question) throw new Error('Main input error: chatInput must contain a non-empty user question.');
return [{ json: { question,} }];
